package com.mannvaasam.controller;
import com.mannvaasam.model.*; import com.mannvaasam.repo.OrderRepository; import com.mannvaasam.service.CurrentUserService; import com.mannvaasam.service.OrderService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/sellers/orders") @PreAuthorize("hasRole('SELLER')") public class SellerOrderController { final OrderRepository orders; final CurrentUserService current; final OrderService service; public SellerOrderController(OrderRepository o,CurrentUserService c,OrderService s){orders=o;current=c;service=s;} @GetMapping public List<Order> all(){return orders.findBySellerOrderByCreatedAtDesc(current.get());} @PatchMapping("/{id}/status") public Order status(@PathVariable Long id,@RequestParam OrderStatus status){return service.updateSeller(id,status);} }